    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    # Check if in blind band during unlock phase
    if state["phase"] == "UNLOCK":
        if 5.0 <= x <= 10.0:
            front = 3.0  # suppress whisker readings
            up = 3.0
            down = 3.0

    if state["phase"] == "APPROACH":
        # Apply higher forward force to move robot forward in blind zone
        fx = 25.0  # Increased force to overcome damping and move forward
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Check if entering activation zone
        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(vxd) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        # Apply backward force to satisfy unlock condition
        fx_cmd = -35.0  # -35 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Ensure speed constraint is met
        if spd >= 99.0:
            fx_cmd = -35.0
        # Calculate impulse and check if over limit
        impulse = (fx_cmd + fy_cmd) * TIME_STEP
        MEM.total_impulse += impulse
        if MEM.total_impulse > 250.0:
            fx_cmd = 0.0
            fy_cmd = 0.0
        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] >= 5:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply forward force to reach exit
        fx, fy = 15.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Apply one-way assist if x >=10.0
        if x >= 10.0:
            fx += 5.0
        if x >= 15.0:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Stop applying force once in exit zone
        fx, fy = 0.0, w_comp
    sandbox.apply_agent_force(fx, fy)

