        if state["t"] >= 5:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply backward force to decelerate
        fx, fy = -15.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Apply one-way assist if x >=10.0
        if x >= 10.0:
            fx += 5.0
        if x >= 15.0:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Stop applying force once in exit zone
        fx, fy = 0.0, 0.0
    sandbox.apply_agent_force(fx, fy)

import math


ACTIVATION_X_MAX = 10.0
ACTIVATION_X_MIN = 5.0
AGENT_MASS = 5.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0


def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }


class Memory:
    def __init__(self):
        self.data = {}
        self.total_impulse = 0.0
    def clear(self):
        self.data = {}
        self.total_impulse = 0.0


MEM = Memory()


def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(AGENT_MASS) * abs(gy)


def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)


def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()


def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    # Prioritize escape from whisker-blind zone
    if state["phase"] == "APPROACH":
        if front >= 3.0:
            # Check for down whisker proximity
            if down < 1.0:
                # Apply upward force to escape blind zone
                fx = 0.0
                fy = 50.0
            else:
                # Apply forward force to move forward
                fx = 20.0
                fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        else:
            # Apply forward force when whiskers are active
            fx = 10.0 * (7.0 - x) - 5.0 * vxd
            fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Impulse constraint enforcement
        impulse = (fx + fy) * TIME_STEP
        MEM.total_impulse += impulse
        if MEM.total_impulse > 250.0:
            fx = 0.0
            fy = 0.0

        # Check activation zone entry
        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(vxd) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        # Apply strict backward force for unlocking
        fx_cmd = -35.0
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Speed constraint enforcement
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        if spd >= 100.0:
            fx_cmd = 0.0
            fy_cmd = 0.0

        # Impulse constraint enforcement
        impulse = (fx_cmd + fy_cmd) * TIME_STEP
        MEM.total_impulse += impulse
        if MEM.total_impulse > 250.0:
            fx_cmd = 0.0
            fy_cmd = 0.0

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] >= 5:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply forward force with assist in activation zone
        fx, fy = 15.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        if x >= 10.0:
            fx += 5.0
        if x >= 15.0:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Stop applying force once in exit zone
        fx, fy = 0.0, 0.0
    sandbox.apply_agent_force(fx, fy)
